    32→};
    33→export type ToastWithMetadata = { metadata: ToastMetadata, descriptor: ToastDescriptor };
    34→export type ToastStorage = Readonly<Record<ToastId, ToastWithMetadata>>;
    35→export type ToastSubscriber = (this: ToastStore, toasts: ToastStorage) => void;
    36→
    37→/**
    38→ * Store for the currently active toasts. Can be subscribed to to get notified when the state changes.
    39→ */
    40→export class ToastStore {
    41→  #options: Required<ToastStoreOptions>;
    42→  
    43→  #idCounter = 0; // Maintain a count for automatic ID generation
    44→  #toasts: ToastStorage = Object.create(null);
    45→  #subscribers: Set<ToastSubscriber> = new Set();
    46→  #dedupeKeys: Set<string> = new Set(); // Tracks active dedupe keys to prevent showing duplicate notifications.
